style.css:
/* Set the default text color for the whole page */
html, body { color: #8ccf9b; }

/* Ensure common elements also use it */
a, a:visited, a:hover, a:active { color: #8ccf9b; }
input, textarea, select, button { color: #8ccf9b; }

/* Optional: make SVG icons follow the text color */
svg { color: #8ccf9b; }
svg * { fill: currentColor; stroke: currentColor; }
